/**
 * Original planning drafts for dish-surface names without a normalized recipe-title
 * match in the October 2026 menu snapshot. These do not replace existing recipes.
 * Quantities and ten-portion yields are estimates, not validated production data.
 */
export interface MenuRecipeDraft {
  menuName: string;
  title: string;
  description: string;
  yieldPortions: number;
  ingredients: string[];
  steps: string[];
  equipmentMethods: { thermomix: string[]; ninja: string[]; riceCooker: string[] };
  notes: string;
  purchased: boolean;
}

const reviewNote = "DRAFT: cantidades y rendimiento estimados, no verificados; requiere revisión de cocina antes de aprobar. No representa nutrición verificada. Validar funciones, accesorios, límites y manejo de alimentos calientes en el manual oficial del modelo Thermomix, Ninja o arrocera disponible; modelo y capacidad desconocidos. No se prescriben programas, tiempos ni tamaños de lote para estos aparatos. Mantener cadena de frío y separar crudos de alimentos listos para comer.";

const riceComponents: Record<string, string> = {
  "Arroz Blanco": "Cocer únicamente el arroz y sus aromáticos si el manual autoriza esos ingredientes. Sofreír cebolla y ajo en olla convencional aparte; validar proporción de líquido, carga y procedimiento para el arroz elegido.",
  "Arroz Naranja": "Sólo cocer esta mezcla si el manual autoriza jugos e ingredientes adicionales; no asumir que admite azúcar o líquidos ácidos. Si no los autoriza, seguir la cocción en olla convencional de los pasos; no sustituir silenciosamente el jugo por agua.",
  "Pastel de sushi": "Cocer sólo el arroz sin rellenos si el manual admite ese tipo de grano, validando líquido y carga. Añadir el aderezo fuera del aparato; enfriar rápidamente y refrigerar según protocolo para arroz, sin dejarlo templado en la arrocera.",
  "Caldo de Albóndigas": "Puede preparar únicamente el arroz del relleno según el manual, validando líquido y carga. Enfriar rápidamente antes de mezclar con la carne; las albóndigas y el caldo requieren olla convencional, no cocer carne cruda en la arrocera por suposición.",
};

function draft(
  menuName: string,
  description: string,
  ingredients: string[],
  steps: string[],
  component: string,
  conventional: string,
  uncertainty = "",
): MenuRecipeDraft {
  return {
    menuName,
    title: menuName,
    description,
    yieldPortions: 10,
    ingredients,
    steps,
    equipmentMethods: {
      thermomix: [
        `Sólo como apoyo, si el manual oficial del modelo lo permite: ${component}.`,
        `Equipo convencional necesario: ${conventional}. No sustituir fritura, horneado ni sellado por cocción lenta.`,
      ],
      ninja: [
        `Sólo si el modelo y accesorio disponibles permiten procesar alimentos: ${component}; de lo contrario hacerlo manualmente. No se presupone licuadora, horno ni freidora.`,
        `Equipo convencional necesario: ${conventional}. Una olla de cocción lenta no sustituye fritura, horneado ni sellado.`,
      ],
      riceCooker: [
        riceComponents[menuName]
          ? `Uso opcional de arrocera, sujeto al manual oficial del modelo y a revisión de cocina: ${riceComponents[menuName]} No se asumen programa, tiempo ni capacidad.`
          : "No aplica a esta base: no requiere cocción de arroz. No usar la arrocera como sustituto de fritura, horneado o sellado; seguir los equipos convencionales indicados.",
      ],
    },
    notes: [reviewNote, uncertainty].filter(Boolean).join(" "),
    purchased: false,
  };
}

function purchasedDrink(menuName: string): MenuRecipeDraft {
  return {
    menuName,
    title: menuName,
    description: `Producto comprado: ${menuName.toLowerCase()} en envase individual cerrado; sabor y volumen pendientes de selección.`,
    yieldPortions: 10,
    ingredients: [`10 envases individuales de ${menuName.toLowerCase()} (volumen y sabor por confirmar en etiqueta)`],
    steps: [
      "Seleccionar marca, sabor y presentación con cocina; comprobar etiquetas, integridad y fecha de consumo.",
      "Enfriar según etiqueta y entregar un envase cerrado por porción; registrar el volumen real antes de aprobar.",
    ],
    equipmentMethods: {
      thermomix: ["No requiere Thermomix: producto comprado y porcionado, sin cocción ni procesamiento."],
      ninja: ["No requiere Ninja: producto comprado y porcionado, sin cocción ni procesamiento."],
      riceCooker: ["No aplica: bebida comprada en envase cerrado; no requiere arrocera ni calentamiento."],
    },
    notes: `${reviewNote} Producto comprado: no es una fórmula de refresco casero. Marca, sabor y volumen pendientes de selección; diez envases son diez porciones estimadas.`,
    purchased: true,
  };
}

